import scipy.special as sp
def gelu(x): return 0.5*x*(1+sp.erf(x/np.sqrt(2)))
y=labels(); d=np.load('base_feats.npz'); N=len(y); Y=np.eye(8)[y]
def cn(X):
    X=X[:,KEEP].astype(np.float64); X=X-X.mean(0); return X/np.linalg.norm(X,axis=1,keepdims=True)
def cen(X):
    X=X[:,KEEP].astype(np.float64); X=X-X.mean(0); return X/np.sqrt((X**2).sum(1).mean())
Z9=cn(d['mean_hidden_L9']); C0=cen(d['mean_hidden_L0'])
def anchor_cv(a, b, nanch=1000, lam=1e-2, wl=1.0, seeds=(0,1), k=10):
    accs=[]
    for s in seeds:
        f=folds(y,k,s); S=np.zeros((N,8)); rng=np.random.RandomState(s)
        for i in range(k):
            tr=np.where(f!=i)[0]; te=np.where(f==i)[0]
            anc=rng.choice(tr, min(nanch,len(tr)), replace=False)
            Phi=gelu(a*(Z9@Z9[anc].T)+b)
            F=np.hstack([Phi, wl*C0]) if wl>0 else Phi
            mu=F[tr].mean(0); Fc=F-mu
            Wt=np.linalg.solve(Fc[tr].T@Fc[tr]+lam*np.eye(F.shape[1]), Fc[tr].T@(Y[tr]-Y[tr].mean(0)))
            S[te]=Fc[te]@Wt
        accs.append((S.argmax(1)==y).mean())
    return round(float(np.mean(accs)),4)
